{"code":"local grid = {'S#G','.#.','a#.'}
local tel = {{fr=1,fc=1,tr=3,tc=1,cost=0}}
local R = #grid; local C = #grid[1]
local log = {}
table.insert(log, 'R='..R..' C='..C)
for r=1,R do table.insert(log, 'row'..r..'='..string.sub(grid[r],1,C)) end
-- build tel map
local telBySrc = {}
for i=1,#tel do
  local t=tel[i]
  local src=(t.fr-1)*C+(t.fc-1)
  local dst=(t.tr-1)*C+(t.tc-1)
  table.insert(telBySrc, {}) -- dummy
  telBySrc[src] = telBySrc[src] or {}
  table.insert(telBySrc[src], {d=dst, cost=t.cost})
  table.insert(log, 'src='..src..' dst='..dst)
end
for k,v in pairs(telBySrc) do table.insert(log, 'key '..k..' n='..#v) end
return table.concat(log, ' || ')
"}

