{"code":"logic_define('price', function(qty)
  if not qty or qty <= 0 then return 0 end
  if qty <= 10 then
    return 5 * qty
  elseif qty <= 20 then
    return 50 + 4 * (qty - 10)
  else
    return 90 + 3 * (qty - 20)
  end
end)

report("Defined logic slot 'price' with tiered pricing: first 10 units at 5 gold each, units 11-20 at 4 gold each, units beyond 20 at 3 gold each.")"}

{"code":"logic_define('key_found', function(player_x, player_z, key_x, key_z)
  local dx = player_x - key_x
  local dz = player_z - key_z
  return math.sqrt(dx * dx + dz * dz) <= 2.0
end)
report("Defined logic slot 'key_found': returns true when x/z-plane distance between player and key is <= 2.0 units.")"}
